import java.util.*;

class Solution {
    public int uniquePaths(int rows, int cols) {
        int[] dp = new int[cols];
        Arrays.fill(dp, 1);                 // first row: exactly one route to each cell
        for (int r = 1; r < rows; r++) {
            for (int c = 1; c < cols; c++) {
                dp[c] += dp[c - 1];         // from above (old dp[c]) + from the left
            }
        }
        return dp[cols - 1];
    }
}

